void ams::ShmFlags_Print(ams::ShmFlags row, algo::cstring& str) {
    algo::ListSep ls(",");
    if (write_Get(row)) {
        str << ls << "write";
    }
    if (read_Get(row)) {
        str << ls << "read";
    }
    if (write_err_Get(row)) {
        str << ls << "write_err";
    }
    if (signaled_Get(row)) {
        str << ls << "signaled";
    }
}

