    parent.magic = u32(0xc001af01);
    parent.tot_size = u32(0);
    parent.max_msg_size = u32(0);
    parent.offset_mask = u32(0);
    parent.woff = u64(0);
    parent.n_shmember = u32(0);
    parent.max_shmember = u32(0);
